'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=[{name:'Ramkund',lat:20.0067,lon:73.7638,type:'ghat',detail:'Sacred bathing ghat · Panchavati',icon:'≈'},{name:'Kalaram Temple',lat:20.0078,lon:73.7682,type:'temple',detail:'Temple · Panchavati',icon:'♧'},{name:'Sita Gufa',lat:20.0094,lon:73.768,type:'temple',detail:'Sacred cave · Panchavati',icon:'◇'},{name:'Tapovan',lat:20.006,lon:73.795,type:'temple',detail:'Spiritual area · Nashik',icon:'♧'},{name:'Trimbakeshwar Temple',lat:19.9324,lon:73.5306,type:'temple',detail:'Temple · Trimbakeshwar',icon:'♧'}];
let saved=[],home=null,pois=[...initial],selected=null,filter='all',routeLayer=null,routeMarkers=[],requestId=0;const resolved={};
try{saved=JSON.parse(localStorage.getItem('km-places')||'[]').filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));home=JSON.parse(localStorage.getItem('km-home')||'null')}catch{saved=[];home=null}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',5000)}
function persist(){try{localStorage.setItem('km-places',JSON.stringify(saved));localStorage.setItem('km-home',JSON.stringify(home));render()}catch{toast('Device storage is unavailable. Your changes cannot be saved.')}}
if(!window.L){document.body.insertAdjacentHTML('beforeend','<p role="alert">Map could not load. Please check your internet connection and reload.</p>');throw new Error('Map library unavailable')}
const map=L.map('map',{zoomControl:false}).setView([20.008,73.774],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);const markers=L.layerGroup().addTo(map);
function icon(symbol){return L.divIcon({className:'',html:'<div class="marker"><span>'+esc(symbol)+'</span></div>',iconSize:[30,30],iconAnchor:[15,30]})}
function card(p,remove=false){const el=document.createElement('div');el.className='poi';el.tabIndex=0;el.setAttribute('role','button');el.innerHTML='<div class="poi-icon">'+esc(p.icon||'⌖')+'</div><div><b>'+esc(p.name)+'</b><p>'+esc(p.tag||p.detail||'Map location')+'</p></div><span class="arrow">↗</span>';el.onclick=()=>openPlace(p);el.onkeydown=e=>{if(e.key==='Enter')openPlace(p)};if(remove){const b=document.createElement('button');b.textContent='×';b.title='Remove saved place';b.className='text-button';b.onclick=e=>{e.stopPropagation();saved=saved.filter(x=>x.id!==p.id);persist()};el.append(b)}return el}
function render(){const list=$('poiList');list.replaceChildren();pois.filter(p=>filter==='all'||p.type===filter).forEach(p=>list.append(card(p)));$('savedList').replaceChildren();if(!saved.length)$('savedList').innerHTML='<p class="muted">Tap a pin or anywhere on the map to save your first place.</p>';saved.forEach(p=>$('savedList').append(card(p,true)));$('count').textContent=saved.length;$('places').replaceChildren();[...pois,...saved].forEach(p=>{const o=document.createElement('option');o.value=p.name;$('places').append(o)});markers.clearLayers();[...pois,...saved,...(home?[{...home,icon:'⌂'}]:[])].forEach(p=>L.marker([p.lat,p.lon],{icon:icon(p.icon||'⌖')}).addTo(markers).bindTooltip(p.name).on('click',()=>openPlace(p)));$('homeText').textContent=home?home.name+' · saved on this device':'Save your stay, meeting point or parked bus.';$('homeButton').innerHTML=home?'Take me back ↗':'Set home ↗'}
function openPlace(p){selected={...p};$('dialogTitle').textContent=p.name||'Save this spot';$('coords').textContent=p.lat.toFixed(5)+', '+p.lon.toFixed(5);$('placeName').value=p.name||'';$('placeTag').value=p.tag||'Saved place';$('placeNote').value=p.note||'';$('placeDialog').showModal()}
function formPlace(){return {...selected,name:$('placeName').value.trim()||'My saved spot',tag:$('placeTag').value,note:$('placeNote').value.trim()}}
map.on('click',e=>openPlace({lat:e.latlng.lat,lon:e.latlng.lng,name:''}));
$('savePlace').onclick=()=>{const p=formPlace();const old=saved.find(x=>Math.abs(x.lat-p.lat)<.00001&&Math.abs(x.lon-p.lon)<.00001);p.id=old?.id||crypto.randomUUID();saved=saved.filter(x=>x.id!==p.id);saved.push(p);persist();$('placeDialog').close();toast('Place saved on this device')};
$('setHome').onclick=()=>{home=formPlace();persist();$('placeDialog').close();toast('Your way back is saved')};
async function share(p){const url=new URL(location.href);url.search='';url.searchParams.set('lat',p.lat);url.searchParams.set('lon',p.lon);url.searchParams.set('name',p.name||'Shared place');const text=(p.name||'Shared place')+(p.note?' — '+p.note:'');try{if(navigator.share)await navigator.share({title:'KumbhMitra · '+p.name,text,url:url.href});else{await navigator.clipboard.writeText(url.href);toast('Location link copied')}}catch(e){if(e.name!=='AbortError')prompt('Copy this location link',url.href)}}
$('sharePlace').onclick=()=>share(formPlace());
function setField(key,p){resolved[key]={...p};$(key).value=p.name||'Selected map location'}
$('setDestination').onclick=()=>{setField('end',formPlace());$('placeDialog').close();tab('explore');toast('Destination selected. Choose a starting point.')};$('setStart').onclick=()=>{setField('start',formPlace());$('placeDialog').close();tab('explore')};
['start','end'].forEach(key=>$(key).addEventListener('input',()=>delete resolved[key]));
$('swap').onclick=()=>{const val=$('start').value;$('start').value=$('end').value;$('end').value=val;const p=resolved.start;resolved.start=resolved.end;resolved.end=p};
function gps(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('Location is unavailable in this browser.'));navigator.geolocation.getCurrentPosition(p=>resolve({name:'My current location',lat:p.coords.latitude,lon:p.coords.longitude}),()=>reject(new Error('Could not get your location. Allow location access or type a starting point.')),{enableHighAccuracy:true,timeout:15000,maximumAge:30000})})}
async function locate(){try{const p=await gps();setField('start',p);map.setView([p.lat,p.lon],16);L.circleMarker([p.lat,p.lon],{radius:7,color:'#fff',fillColor:'#2474c5',fillOpacity:1,weight:3}).addTo(markers);toast('Current location selected as your starting point')}catch(e){toast(e.message)}}$('locate').onclick=locate;$('mapLocate').onclick=locate;$('zoomIn').onclick=()=>map.zoomIn();$('zoomOut').onclick=()=>map.zoomOut();
async function fetchJSON(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});if(!r.ok)throw new Error('The map service is busy. Please try again shortly.');return r.json()}
async function resolvePlace(key){const q=$(key).value.trim();if(!q)throw new Error('Enter both a starting point and destination.');if(resolved[key])return resolved[key];const found=[...saved,...pois].find(p=>p.name.toLowerCase()===q.toLowerCase());if(found)return found;const data=await fetchJSON('https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=in&q='+encodeURIComponent(q+' Nashik'));if(!data.length)throw new Error('Could not find “'+q+'”. Select a suggested place or tap the map.');return {name:data[0].display_name,lat:+data[0].lat,lon:+data[0].lon}}
async function route(){const id=++requestId;const button=$('route');button.disabled=true;button.textContent='Finding your walk…';if(routeLayer){map.removeLayer(routeLayer);routeLayer=null}routeMarkers.forEach(m=>map.removeLayer(m));routeMarkers=[];$('routeResult').hidden=true;try{const a=await resolvePlace('start'),b=await resolvePlace('end');if(Math.abs(a.lat-b.lat)+Math.abs(a.lon-b.lon)<.00002)throw new Error('Choose two different places for your walk.');const data=await fetchJSON('https://routing.openstreetmap.de/routed-foot/route/v1/foot/'+a.lon+','+a.lat+';'+b.lon+','+b.lat+'?overview=full&geometries=geojson&steps=true');if(id!==requestId)return;if(data.code!=='Ok'||!data.routes?.length)throw new Error('No walking route found. Try a nearby starting point.');const r=data.routes[0];routeLayer=L.geoJSON(r.geometry,{style:{color:'#22593e',weight:6,opacity:.85}}).addTo(map);routeMarkers=[L.marker([a.lat,a.lon],{icon:icon('A')}).addTo(map),L.marker([b.lat,b.lon],{icon:icon('B')}).addTo(map)];map.fitBounds(routeLayer.getBounds(),{padding:[50,90]});const min=Math.max(1,Math.round(r.distance/75));const steps=r.legs.flatMap(l=>l.steps).map(s=>{const type=s.maneuver.type.replaceAll('_',' ');return '<li>'+esc(type==='arrive'?'Arrive at your destination':type==='depart'?'Start walking':type+(s.maneuver.modifier?' '+s.maneuver.modifier:''))+(s.name?' on '+esc(s.name):'')+' <span class="muted">· '+Math.round(s.distance)+' m</span></li>'}).join('');$('routeResult').innerHTML='<b>'+esc((r.distance/1000).toFixed(1))+' km <span class="muted">· about '+(min>=60?Math.floor(min/60)+' hr ':'')+(min%60)+' min</span></b><p>Estimated at a relaxed 4.5 km/h. Crowds, steps and barriers can add time. This route is not verified for Kumbh access.</p><details><summary>Walking track details</summary><ol>'+steps+'</ol></details><button id="externalRoute" class="text-button">Open walking navigation in Google Maps ↗</button>';$('externalRoute').onclick=()=>window.open('https://www.google.com/maps/dir/?api=1&origin='+a.lat+','+a.lon+'&destination='+b.lat+','+b.lon+'&travelmode=walking','_blank','noopener');$('routeResult').hidden=false;tab('explore')}catch(e){toast(e.name==='TimeoutError'?'Walking service timed out. Try again shortly.':e.message)}finally{button.disabled=false;button.innerHTML='Find walking route <span>↗</span>'}}
$('route').onclick=route;
$('homeButton').onclick=async()=>{if(!home){try{const p=await gps();openPlace({...p,name:'My stay / bus'});$('placeTag').value='Home / stay'}catch(e){toast('Tap your stay or bus location on the map, then choose “Set as my way back”.')}return}setField('end',home);tab('explore');try{const p=await gps();setField('start',p);await route()}catch(e){toast(e.message+' Your return destination is selected.')}};
function tab(which){$('planner').hidden=which!=='explore';$('savedPanel').hidden=which!=='saved';$('planTab').classList.toggle('active',which==='explore');$('savedTab').classList.toggle('active',which==='saved');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===which))}document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('planTab').onclick=()=>tab('explore');$('savedTab').onclick=()=>tab('saved');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render()});
$('nearby').onclick=async()=>{const b=$('nearby');b.disabled=true;b.textContent='Looking for nearby essentials…';try{if(map.getZoom()<13)throw new Error('Zoom in to a neighbourhood to find nearby essentials.');const bounds=map.getBounds(),box=[bounds.getSouth(),bounds.getWest(),bounds.getNorth(),bounds.getEast()].join(',');const q='[out:json][timeout:15];nwr[amenity~"^(toilets|drinking_water|hospital|pharmacy|restaurant)$"]('+box+');out center 50;';const data=await fetchJSON('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'data='+encodeURIComponent(q)});const found=data.elements.map(x=>({name:x.tags.name||x.tags.amenity.replaceAll('_',' '),lat:x.lat??x.center.lat,lon:x.lon??x.center.lon,type:'amenity',detail:x.tags.amenity.replaceAll('_',' ')+' · OSM, opening status unverified',icon:'⌖'}));pois=[...initial,...found];filter='all';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter==='all'));render();toast(found.length?found.length+' mapped essentials found. Check availability locally.':'No mapped essentials found in this area.')}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='＋ Find essentials in this map area'}};
render();const params=new URLSearchParams(location.search);if(params.has('lat')&&params.has('lon')){const lat=Number(params.get('lat')),lon=Number(params.get('lon'));if(Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180){const p={lat,lon,name:(params.get('name')||'Shared place').slice(0,100)};map.setView([lat,lon],16);setTimeout(()=>openPlace(p),300)}}
